'use client';

import { useActionState } from 'react';

async function submitContactMessage(prevState: { error?: string }, formData: FormData) {
  'use server';

  const name = formData.get('name') as string | null;
  const email = formData.get('email') as string | null;
  const message = formData.get('message') as string | null;

  // Validation: check that all fields are provided
  if (!name || name.trim() === '') {
    return { error: 'Name is required.' };
  }
  if (!email || email.trim() === '') {
    return { error: 'Email is required.' };
  }
  if (!message || message.trim() === '') {
    return { error: 'Message is required.' };
  }

  // Simulate saving the contact message
  console.log('Contact message received:', { name: name.trim(), email: email.trim(), message: message.trim() });

  return { error: undefined };
}

export default function ContactForm() {
  const [state, formAction] = useActionState(submitContactMessage, { error: undefined });

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={formAction}>
        <div>
          <label htmlFor="name">Name</label>
          <input id="name" name="name" type="text" placeholder="Your name" required />
        </div>
        <div>
          <label htmlFor="email">Email</label>
          <input id="email" name="email" type="email" placeholder="your@email.com" required />
        </div>
        <div>
          <label htmlFor="message">Message</label>
          <textarea id="message" name="message" placeholder="Your message" required rows={5} />
        </div>
        {state?.error && <p style={{ color: 'red' }}>{state.error}</p>}
        <button type="submit">Send Message</button>
      </form>
    </div>
  );
}

